// Mock of the Freya Bank statement/debt voice services (service contract of 1 October 2026).
// Generated by build_worker.py: DATA is the bank's test-customers.json, served exactly (status code and body).
const DATA = __DATA__;

const CORS = { "Access-Control-Allow-Origin": "*" };
const BY_NO = Object.fromEntries(DATA.customers.map((c) => [String(c.customerNo), c]));

const NOT_FOUND = {
  "cards.list": ["FB_IVR_CHANNEL_102", "Müşteriye ait geçerli kart bilgisi bulunamadı."],
  "cards.balance": ["FB_IVR_CHANNEL_120", "Kart bakiye servisi hatası: kart bulunamadı"],
  "statement.week.get": ["FB_IVR_CHANNEL_121", "Kart bulunamadı"],
  "statement.pdf.send": ["FB_IVR_CHANNEL_107", "Pdf dokümanı bulunamadı"],
};

function guid() { return crypto.randomUUID().replace(/-/g, ""); }

function errorBody(code, text, type) {
  const g = guid();
  return { result: { guid: g, returnCode: code, messageText: text, code: code, message: text, type: type,
    details: { guid: g, rootCause: type === "WARNING" ? "NotFoundException" : "InvalidArgument", errorOrigin: "ivr-gateway-test:ivr-channel-v0" } } };
}
function reply(body, status) { return Response.json(body, { status: status, headers: CORS }); }
function bad(field) { return reply(errorBody("INVALID_ARGUMENTS_ERROR", field + " cannot be empty", "ERROR"), 400); }
function notFound(service) {
  const nf = NOT_FOUND[service];
  if (nf) return reply(errorBody(nf[0], nf[1], "WARNING"), 404);
  return reply(errorBody("INVALID_ARGUMENTS_ERROR", "invalid arguments", "ERROR"), 400);
}
// The panel's "Test API Request" button sends variables unfilled ("{{customerNumber}}"): answer with a valid record.
function isTemplate(v) { return typeof v === "string" && (v.startsWith("{{") || v.startsWith("%7B%7B")); }
function empty(v) { return v === undefined || v === null || String(v).trim() === ""; }
function sleep(s) { return new Promise((r) => setTimeout(r, s * 1000)); }

async function answer(entry) {
  if (entry.delaySeconds) await sleep(entry.delaySeconds);
  return reply(entry.response, entry.http);
}

async function service(name, d) {
  d = d || {};
  if (name === "cards.list" || name === "contact.email.get" || name === "statement.pdf.send") {
    let no = d.customerNo;
    if (empty(no)) return bad("customerNo");
    if (isTemplate(no)) no = DATA.customers[0].customerNo;
    if (name === "contact.email.get" && empty(d.intAddressInfoType)) return bad("intAddressInfoType");
    if (name === "statement.pdf.send") {
      for (const f of ["cardNumber", "currencyType", "statementDate", "emailAddress"]) if (empty(d[f])) return bad(f);
    }
    const c = BY_NO[String(no).trim()];
    const e = c && c.services[name];
    return e ? answer(e) : notFound(name);
  }
  if (empty(d.cardNumber)) return bad("card number");
  let card = String(d.cardNumber).trim();
  const find = (svc) => {
    for (const c of DATA.customers) { const m = c.services[svc]; if (m && m[card]) return m[card]; }
    return null;
  };
  if (isTemplate(card)) { card = Object.keys(DATA.customers[0].services[name])[0]; }
  const m = find(name);
  if (name === "statement.week.decide" || name === "statement.week.change") {
    if (empty(d.newStatementWeek)) return bad("newStatementWeek");
    if (empty(d.statementDay)) return bad("statementDay");
    const e = m && m[String(d.newStatementWeek).trim()];
    return e ? answer(e) : notFound(name);
  }
  return m ? answer(m) : notFound(name);
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: { ...CORS, "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "*" } });
    }
    if (request.method === "GET" && url.pathname === "/health") return reply({ durum: "ok" }, 200);
    if (request.method === "POST" && url.pathname.endsWith("/oauth2/token")) {
      return reply({ access_token: "mock-token", token_type: "Bearer", expires_in: 1800 }, 200);
    }
    if (request.method === "POST") {
      const name = url.pathname.replace(/^\/(voice\/v1\/)?/, "");
      if (["cards.list", "cards.balance", "statement.week.get", "statement.week.decide", "statement.week.change",
           "contact.email.get", "statement.pdf.send"].includes(name)) {
        let body = null;
        try { body = await request.json(); } catch (e) { body = null; }
        return service(name, body && body.data);
      }
    }
    return reply({ hata: "bulunamadı" }, 404);
  },
};
